2026-08-08 11:48:32,751 [INFO ] [main] com.armedia.acm.services.ocr.rules.OCRBusinessProcessRulesTest - DRL: package OCR_Workflow_Rules;
//generated from Decision Table
import com.armedia.acm.services.mediaengine.model.MediaEngineBusinessProcessModel;
import org.springframework.expression.EvaluationContext;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;

function Boolean evalSpring(String expression, Object obj)
{
    ExpressionParser ep = new SpelExpressionParser();
    Expression exp = ep.parseExpression(expression);
    EvaluationContext ec = new StandardEvaluationContext();

    Boolean evaluated = exp.getValue(ec, obj, Boolean.class);

    return evaluated;
}
// rule values at C17, header at C12
rule "OCR Workflow Rules_17"
	salience 65535
	when
		$model: MediaEngineBusinessProcessModel(eval(evalSpring("type == 'AUTOMATIC'", $model)))
	then
		$model.setStart(true);
		$model.setName("MediaEngineWorkFlow");
end

// rule values at C18, header at C12
rule "OCR Workflow Rules_18"
	salience 65534
	when
		$model: MediaEngineBusinessProcessModel(eval(evalSpring("type == 'MANUAL'", $model)))
	then
		$model.setStart(true);
		$model.setName("MediaEngineWorkFlow");
end


